SourceCode.Declaration:
/// <summary>
/// PricingAttribute of table <c>InventTable</c> field sortCode.
/// </summary>
[UPSPricingMetadataDiscovery][UPSPricingAttributeSourceDiscovery(UPSPricingAttributeSource::Product, UPSPricingAttributeSourceLevel::Line)]
internal class UPSPricingAttributeInventTableSortCode extends UPSPricingAttributeInventTable implements UPSIPricingAttribute
{
}

Method.Source:
public str getName()
{
    return fieldPName(InventTable, sortCode);
}

public Set getAllowedValues()
{
    var         ret = new Set(Types::Integer);
    InventTable inventTable;

    while select inventTable
        group by sortCode
    {
        if (! ret.in(inventTable.sortCode))
        {
            ret.add(inventTable.sortCode);
        }
    }

    return ret;
}

protected void setQueryBuildDatasourceRange(QueryBuildDataSource _qbds, anytype _value)
{
    QueryBuildRange qbr;

    qbr = _qbds.addRange(fieldNum(InventTable, sortCode));
    qbr.value(queryValue(_value));
}
